window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6606910508850f84"]={"versions": [{"id": "FIG-6606910508850f84", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenz- und Interaktionsdiagramm im AUTOSAR-Classic-Diagnose- und Fehlerspeicher-Kontext (AUTOSAR SWS DCM). Das Diagramm illustriert die Abwicklung des UDS-Dienstes <code>$19 04</code> (<em>Report DTC Snapshot Record By DTC Number</em>) zur Abfrage von Freeze-Frame- bzw. Snapshot-Daten zwischen einem externen Diagnose-Tester, dem Diagnostic Communication Manager (DCM) und dem Diagnostic Event Manager (DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>External Tester</strong>: Externes Diagnoseprüfgerät, kommuniziert über standardisierte UDS-Diagnosebotschaften mit dem DCM.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Protokollierung und Weiterleitung von Diagnoseanforderungen an Basissoftware-Module.\n</li><li><strong>DEM (Diagnostic Event Manager)</strong>: BSW-Modul zur Verwaltung von Diagnoseereignissen, Event Memory (Ereignisspeicher mit DTC-Einträgen und Freeze-Frame-Sets) und zugehörigen Snapshots.\n</li><li><strong>Schnittstellen / Aufrufe (DCM an DEM)</strong>:\n<ul class=\"fig-list\"><li><code>Dem_GetStatusOfDTC</code>: Funktionsaufruf zur Abfrage des aktuellen Status eines DTCs.\n</li><li><code>Dem_GetFreezeFrameDataIdentifiersByDTC</code>: Funktionsaufruf zum Abfragen der Liste gespeicherter Daten-Identifikatoren (DataIDs) für den spezifizierten DTC.\n</li><li><code>Dem_DisableDTCRecordUpdate</code>: Funktionsaufruf zur Sperrung der Aktualisierung von Snapshot-Datensätzen im DEM während des Lesevorgangs.\n</li><li><code>Dem_GetFreezeFrameDataByDTC</code>: Funktionsaufruf zum Auslesen des eigentlichen Snapshot-Datensatzes.\n</li><li><code>Dem_EnableDTCRecordUpdate</code>: Funktionsaufruf zur Freigabe der Aktualisierung von Snapshot-Datensätzen im DEM nach Abschluss des Lesevorgangs.\n</li></ul>\n</li><li><strong>Rückgabewerte (DEM an DCM)</strong>:\n<ul class=\"fig-list\"><li><code>DTCStatus</code>\n</li><li><code>List of DataIDs</code>\n</li><li><code>Snapshot record(s)</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <strong>External Tester</strong> sendet die UDS-Anforderung <code>Request: $19 $04 (DTC + RecordNumber)</code> an den <strong>DCM</strong>.\n</li><li>Der <strong>DCM</strong> ruft am <strong>DEM</strong> <code>Dem_GetStatusOfDTC</code> auf und empfängt als Rückgabewert <code>DTCStatus</code>.\n</li><li>Der <strong>DCM</strong> ruft <code>Dem_GetFreezeFrameDataIdentifiersByDTC</code> auf und erhält als Rückgabewert die <code>List of DataIDs</code>.\n</li><li>Der <strong>DCM</strong> sperrt die Aktualisierung des Datensatzes über <code>Dem_DisableDTCRecordUpdate</code>.\n</li><li>Der <strong>DCM</strong> fordert über <code>Dem_GetFreezeFrameDataByDTC</code> die Snapshot-Daten an und empfängt <code>Snapshot record(s)</code>.\n</li><li>Der <strong>DCM</strong> gibt die Datensatzaktualisierung über <code>Dem_EnableDTCRecordUpdate</code> wieder frei.\n</li><li>Der <strong>DCM</strong> sendet die positive UDS-Antwort <code>Response: $59 $04 (DTC + DTCStatus + RecordNumber + Number of Identifiers + SnapshotData)</code> an den <strong>External Tester</strong> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Record-Nummerierung</strong>: Gemäß textuellem Hinweis müssen <code>RecordNumbers</code> absolute Werte sein (<code>RecordNumbers must be absolute</code>).\n</li><li><strong>Konsistenzschutz / Sperre</strong>: Das Auslesen von Snapshot-Daten erfordert die gezielte Verriegelung (<code>Dem_DisableDTCRecordUpdate</code>) und anschließende Freigabe (<code>Dem_EnableDTCRecordUpdate</code>) des Event Memory, um Dateninkonsistenzen bei zeitgleicher Aktualisierung im Fehlerfall zu verhindern. In diesem Ablauf umschließt die Sperre den Abruf der eigentlichen Daten (<code>Dem_GetFreezeFrameDataByDTC</code>), während die Identifikatoren zuvor außerhalb der Sperre abgefragt werden.\n</li></ul>"}, {"id": "FIG-a7a1fd727de38efb", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Sequenz- und Interaktionsdiagramm im AUTOSAR-Classic-Diagnose- und Fehlerspeicher-Kontext (AUTOSAR SWS DCM). Das Diagramm illustriert die Abwicklung des UDS-Dienstes <code>$19 04</code> (<em>Report DTC Snapshot Record By DTC Number</em>) zur Abfrage von Freeze-Frame- bzw. Snapshot-Daten zwischen einem externen Diagnose-Tester, dem Diagnostic Communication Manager (DCM) und dem Diagnostic Event Manager (DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>External Tester</strong>: Externes Diagnoseprüfgerät, kommuniziert über standardisierte UDS-Diagnosebotschaften mit dem DCM.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Protokollierung und Weiterleitung von Diagnoseanforderungen an Basissoftware-Module.\n</li><li><strong>DEM (Diagnostic Event Manager)</strong>: BSW-Modul zur Verwaltung von Diagnoseereignissen, Event Memory (Ereignisspeicher mit DTC-Einträgen und Freeze-Frame-Sets) und zugehörigen Snapshots.\n</li><li><strong>Schnittstellen / Aufrufe (DCM an DEM)</strong>:\n<ul class=\"fig-list\"><li><code>Dem_GetStatusOfDTC</code>: Funktionsaufruf zur Abfrage des aktuellen Status eines DTCs.\n</li><li><code>Dem_GetFreezeFrameDataIdentifiersByDTC</code>: Funktionsaufruf zum Abfragen der Liste gespeicherter Daten-Identifikatoren (DataIDs) für den spezifizierten DTC.\n</li><li><code>Dem_DisableDTCRecordUpdate</code>: Funktionsaufruf zur Sperrung der Aktualisierung von Snapshot-Datensätzen im DEM während des Lesevorgangs.\n</li><li><code>Dem_GetFreezeFrameDataByDTC</code>: Funktionsaufruf zum Auslesen des eigentlichen Snapshot-Datensatzes.\n</li><li><code>Dem_EnableDTCRecordUpdate</code>: Funktionsaufruf zur Freigabe der Aktualisierung von Snapshot-Datensätzen im DEM nach Abschluss des Lesevorgangs.\n</li></ul>\n</li><li><strong>Rückgabewerte (DEM an DCM)</strong>:\n<ul class=\"fig-list\"><li><code>DTCStatus</code>\n</li><li><code>List of DataIDs</code>\n</li><li><code>Snapshot record(s)</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <strong>External Tester</strong> sendet die UDS-Anforderung <code>Request: $19 $04 (DTC + RecordNumber)</code> an den <strong>DCM</strong>.\n</li><li>Der <strong>DCM</strong> ruft am <strong>DEM</strong> <code>Dem_GetStatusOfDTC</code> auf und empfängt als Rückgabewert <code>DTCStatus</code>.\n</li><li>Der <strong>DCM</strong> sperrt die Aktualisierung des DTC-Datensatzes vorab mittels <code>Dem_DisableDTCRecordUpdate</code>.\n</li><li>Der <strong>DCM</strong> ruft <code>Dem_GetFreezeFrameDataIdentifiersByDTC</code> auf und erhält als Rückgabewert die <code>List of DataIDs</code>.\n</li><li>Der <strong>DCM</strong> ruft <code>Dem_GetFreezeFrameDataByDTC</code> auf und empfängt <code>Snapshot record(s)</code>.\n</li><li>Der <strong>DCM</strong> gibt die Aktualisierung des DTC-Datensatzes über <code>Dem_EnableDTCRecordUpdate</code> wieder frei.\n</li><li>Der <strong>DCM</strong> sendet die UDS-Antwort <code>Response: $59 $04 (DTC + DTCStatus + RecordNumber + Number of Identifiers + SnapshotData)</code> an den <strong>External Tester</strong> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Record-Nummerierung</strong>: Gemäß textuellem Hinweis müssen <code>RecordNumbers</code> absolute Werte sein (<code>RecordNumbers must be absolute</code>).\n</li><li><strong>Konsistenzschutz / Sperre</strong>: Das Auslesen von Snapshot-Daten erfordert die gezielte Verriegelung (<code>Dem_DisableDTCRecordUpdate</code>) und anschließende Freigabe (<code>Dem_EnableDTCRecordUpdate</code>) im DEM. Die Sperre umschließt sowohl die Abfrage der Daten-Identifikatoren (<code>Dem_GetFreezeFrameDataIdentifiersByDTC</code>) als auch das Auslesen der eigentlichen Snapshot-Daten (<code>Dem_GetFreezeFrameDataByDTC</code>), um Konsistenz zwischen Identifikatoren und Datensatzinhalt sicherzustellen.\n</li></ul>"}], "trans": [{"from": "FIG-6606910508850f84", "to": "FIG-a7a1fd727de38efb", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Sequenzreihenfolge zwischen DCM und DEM: Der Aufruf <code>Dem_DisableDTCRecordUpdate</code> erfolgt vor <code>Dem_GetFreezeFrameDataIdentifiersByDTC</code> (zuvor erfolgte er nach dem Abruf der DataIDs und direkt vor <code>Dem_GetFreezeFrameDataByDTC</code>).\n</li></ul>"}]};
